import Navbar from "../components/Navbar";
import Sidebar from "../components/Sidebar";

export default function DashboardLayout({ title, children }) {
  return (
    <div className="app-shell">
      <Navbar />
      <div className="app-body">
        <Sidebar />
        <main className="content">
          {title && <h1>{title}</h1>}
          {children}
        </main>
      </div>
    </div>
  );
}
